css:
.rc{font-family:Helvetica,Arial,sans-serif;color:#1d2433;font-size:12px}
.rc table{width:100%;border-collapse:collapse}.rc td{vertical-align:top}.rc .r{text-align:right}
.rc .logo{max-height:50px;float:left;margin-right:10px}.rc .sn{font-size:18px;font-weight:700;color:#1f6f5c}
.rc .mu{color:#6b7280;font-size:10.5px}.rc .tt{font-size:18px;font-weight:800;letter-spacing:1.5px}
.rc .bar{height:5px;background:#1f6f5c;border-radius:3px;margin:12px 0}
.rc .info td{padding:6px 8px 6px 0;width:33%}.rc .l{font-size:9.5px;text-transform:uppercase;letter-spacing:.8px;color:#6b7280}
.rc .v{font-size:13px;font-weight:600}.rc .amt{background:#1f6f5c;color:#fff;border-radius:8px;padding:12px 16px;margin:12px 0}
.rc .big{font-size:24px;font-weight:800}.rc .words{font-size:11px;opacity:.9}
.rc .g th{background:#f4f6f8;font-size:10px;text-transform:uppercase;color:#4b5563;padding:6px 8px;text-align:left}
.rc .g td{padding:6px 8px;border-bottom:1px solid #eef1f4}.rc .g th.r{text-align:right}
.rc .sum{margin-top:12px}.rc .sum td{border:1px solid #e3e7ec;padding:8px 10px;width:33%}
.rc .sum td.hl{background:#f4f6f8}.rc .ft{margin-top:14px;text-align:center;color:#6b7280;font-size:10.5px}
